from playwright.sync_api import sync_playwright
import os
base=os.getenv('TEST_URL','http://127.0.0.1:4173/icons/')
with sync_playwright() as p:
 b=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox']);page=b.new_page();page.goto(base,wait_until='networkidle')
 result=page.evaluate('''async()=>{await import('./modules/download.js');const e=document.createElement('lucian-download');e.setAttribute('size','96');e.setProgress(64);document.body.append(e);const svg=e.shadowRoot.querySelector('svg');const results=[];for(const [from,to]of [['idle','progress'],['progress','success'],['success','error'],['error','idle']]){e.setState(from);for(const a of svg.getAnimations({subtree:true}))a.finish();getComputedStyle(svg).opacity;e.setState(to);getComputedStyle(svg).opacity;const animations=svg.getAnimations({subtree:true});for(const a of animations)a.pause();for(let ms=0;ms<=300;ms+=1000/60){for(const a of animations)a.currentTime=ms;const visible=['arrow','progress','check','error'].filter(name=>Number(getComputedStyle(svg.querySelector('[data-part="'+name+'"]')).opacity)>.03);if(visible.length>1)results.push({from,to,ms,visible})}for(const a of animations)a.finish()}e.remove();return results}''')
 assert not result, f'Overlapping mutually exclusive download symbols: {result[:3]}'
 interrupted=page.evaluate('''async()=>{const e=document.createElement('lucian-download');document.body.append(e);e.setProgress(64);const svg=e.shadowRoot.querySelector('svg'),states=['idle','progress','success','error'],issues=[];const flush=()=>getComputedStyle(svg.querySelector('[data-part=arrow]')).opacity;const finish=()=>{for(const a of svg.getAnimations({subtree:true}))a.finish();flush()};for(const from of states)for(const to of states.filter(s=>s!==from))for(const at of [16,50,90,120]){e.setState(from);finish();e.setState(to);flush();for(const a of svg.getAnimations({subtree:true})){a.pause();a.currentTime=at}flush();e.setState(from);flush();const animations=svg.getAnimations({subtree:true});for(const a of animations)a.pause();for(let ms=0;ms<=260;ms+=1000/60){for(const a of animations)a.currentTime=ms;const visible=['arrow','progress','check','error'].filter(name=>Number(getComputedStyle(svg.querySelector('[data-part="'+name+'"]')).opacity)>.03);if(visible.length>1)issues.push({from,to,at,ms,visible})}finish()}e.remove();return issues}''')
 assert not interrupted, f'Interrupted transition overlap: {interrupted[:3]}'
 b.close();print('Download symbol transitions have no overlapping glyphs at 60fps, including 48 interrupted reversals: passed')
